fyi_xmlid = "purchase_request_approval_todo.mail_activity_pr_pa_status_fyi"
fyi_type = env.ref(fyi_xmlid, raise_if_not_found=False)
if fyi_type:
    for rec in records:
        pr = rec.request_id
        if not pr or not pr.requested_by:
            continue
        pr.activity_ids.filtered(
            lambda a: a.activity_type_id == fyi_type and a.user_id.id == pr.requested_by.id
        ).unlink()
        pr.activity_schedule(
            fyi_xmlid,
            summary="แบบรายงานขอให้จัดซื้อจัดจ้าง (พจ.1) %s ถูกปฏิเสธ" % (rec.name or ""),
            user_id=pr.requested_by.id,
        )

